 h,w=G.shape; seen=set(); rooms=[]; lab={}
 for r,c in zip(*np.where(G!=wall)):
  p=(int(r),int(c))
  if p in seen: continue
  st=[p]; seen.add(p); comp=[]
  while st:
   x=st.pop();comp.append(x)
   for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
    y=x[0]+dr,x[1]+dc
    if 0<=y[0]<h and 0<=y[1]<w and G[y]!=wall and y not in seen: seen.add(y);st.append(y)
  i=len(rooms);rooms.append(comp)
  for x in comp:lab[x]=i
