def line_graph_predict(G,wall,source_colors=(7,8),tie_value=None, source_init='adj', bg=None):
 G=np.array(G); h,w=G.shape
 dists={col:np.full((h,w),999,dtype=int) for col in source_colors}
 q=deque()
 # dist zero for wall pixels adjacent to sources, with source colors as separate waves
 for r,c in zip(*np.where(G==wall)):
  r,c=int(r),int(c)
  for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
   rr,cc=r+dr,c+dc
   if 0<=rr<h and 0<=cc<w and int(G[rr,cc]) in source_colors:
    col=int(G[rr,cc])
    if dists[col][r,c]>0:
     dists[col][r,c]=0;q.append((r,c,col))
 while q:
  r,c,col=q.popleft(); nd=dists[col][r,c]+1
  for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
   rr,cc=r+dr,c+dc
   if 0<=rr<h and 0<=cc<w and G[rr,cc]==wall and dists[col][rr,cc]>nd:
